// Consecutive-day streak shared by Mood check-in and Daily Reflection - both
// are meant to feel like a habit loop, not a form, so both read this the
// same way: streak counts backward from today if there's already an entry
// today, otherwise from yesterday (so a missed today doesn't erase yesterday's
// run - it just flags the streak as "at risk" via checkedInToday: false).
function consecutiveDayStreak(entries, getDate) {
  const days = new Set((entries || []).map((entry) => new Date(getDate(entry)).toDateString()));
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(today.getDate() - 1);
  const checkedInToday = days.has(today.toDateString());
  const cursor = checkedInToday ? new Date(today) : yesterday;
  let streak = 0;
  while (days.has(cursor.toDateString())) {
    streak += 1;
    cursor.setDate(cursor.getDate() - 1);
  }
  return { streak, checkedInToday };
}

function moodCheckInStreak() {
  const entries = (trackerState.mood.entries || []).filter((entry) => entry.user_id === currentUserId() || !entry.user_id);
  return consecutiveDayStreak(entries, (entry) => entry.created_at);
}

function reflectionCheckInStreak() {
  const entries = (trackerState.reflectionEntries || []).filter((entry) => entry.user_id === currentUserId() && Array.isArray(entry.tags) && entry.tags.includes("daily"));
  return consecutiveDayStreak(entries, (entry) => entry.createdAt);
}

// A tally row instead of an emoji chip - the streak reads as marks on a
// sheet you've been keeping, not a gamified badge.
function streakChipHTML(streakInfo, noun) {
  const count = Math.max(0, streakInfo.streak);
  const cells = 7;
  const filled = Math.min(count, cells);
  const label = count > 0
    ? `${count}-day ${noun} streak${streakInfo.checkedInToday ? "" : " - not logged today"}`
    : `Start your ${noun} streak today`;
  return `
    <div class="tally-row ${count > 0 && !streakInfo.checkedInToday ? "is-at-risk" : ""}">
      <div class="tally-marks">${Array.from({ length: cells }).map((_, i) => `<span class="tally-mark ${i < filled ? "is-filled" : ""}"></span>`).join("")}</div>
      <span class="tally-label">${escapeHTML(label)}</span>
    </div>
  `;
}

function energyLabel(score) {
  if (score < 25) return "Running on empty";
  if (score < 50) return "Low battery";
  if (score < 75) return "Holding steady";
  return "Fully charged";
}

function energyEmoji(score) {
  if (score < 25) return "🪫";
  if (score < 50) return "🔋";
  if (score < 75) return "⚡";
  return "✨";
}

function triggerCheckInCelebration(message) {
  const toast = document.createElement("div");
  toast.className = "checkin-celebrate-toast";
  toast.textContent = message;
  document.body.appendChild(toast);
  window.setTimeout(() => toast.classList.add("is-leaving"), 1500);
  window.setTimeout(() => toast.remove(), 1900);
}

function createReflectionEntry(mode, content, options = {}) {
  const now = new Date();
  const resurfaceDays = options.resurfaceDays != null ? options.resurfaceDays : REFLECTION_RESURFACE_DAYS[mode] || 30;
  const entry = {
    id: `refl-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    user_id: currentUserId(),
    mode,
    createdAt: now.toISOString(),
    displayTime: now.toLocaleString([], { month: "short", day: "numeric" }),
    resurfaceAt: new Date(now.getTime() + resurfaceDays * 86400000).toISOString(),
    resurfacedAt: null,
    dismissedAt: null,
    ignoredCount: 0,
    content: cleanText(content, 1200),
    linkedDecisionId: options.linkedDecisionId || null,
    tags: options.tags || [mode]
  };
  trackerState.reflectionEntries.unshift(entry);
  saveTrackerState();
  return entry;
}

function allReflectionLikeEntries() {
  const native = trackerState.reflectionEntries.filter((entry) => entry.user_id === currentUserId()).map((entry) => ({ ...entry, _source: "reflection" }));
  const decisions = savedFutureDecisions().map((item) => ({
    id: item.id,
    user_id: item.user_id,
    mode: "decisionJournal",
    createdAt: item.generated_at,
    displayTime: item.display_time,
    resurfaceAt: item.resurfaceAt || new Date(new Date(item.generated_at).getTime() + REFLECTION_RESURFACE_DAYS.decisionJournal * 86400000).toISOString(),
    resurfacedAt: item.resurfacedAt || null,
    dismissedAt: item.dismissedAt || null,
    ignoredCount: item.ignoredCount || 0,
    content: item.decisionMade || item.question,
    tags: ["decision"],
    _source: "futureMirror"
  }));
  const checkBacks = trackerState.futureScans
    .filter((scan) => scan.user_id === currentUserId() && scan.stations && scan.stations.checkBack && scan.stations.checkBack.status === "scheduled")
    .map((scan) => {
      const checkBack = scan.stations.checkBack;
      return {
        id: `${scan.id}-checkback`,
        user_id: scan.user_id,
        mode: "futureScanCheckBack",
        createdAt: checkBack.scheduledAt,
        displayTime: checkBack.dueDisplayTime,
        resurfaceAt: checkBack.resurfaceAt,
        resurfacedAt: checkBack.resurfacedAt || null,
        dismissedAt: checkBack.dismissedAt || null,
        ignoredCount: checkBack.ignoredCount || 0,
        content: `Check back: "${scan.scanContext.rawInput}"`,
        tags: ["futureScan"],
        _source: "futureScan",
        _scanId: scan.id
      };
    });
  return [...native, ...decisions, ...checkBacks];
}

function dueForResurfacing() {
  const now = Date.now();
  return allReflectionLikeEntries().filter((entry) => !entry.dismissedAt && new Date(entry.resurfaceAt).getTime() <= now);
}

function resurfaceEntryOriginal(merged) {
  if (merged._source === "reflection") return trackerState.reflectionEntries.find((entry) => entry.id === merged.id) || null;
  if (merged._source === "futureMirror") return trackerState.futureMirror.saved.find((item) => item.id === merged.id) || null;
  if (merged._source === "futureScan") {
    const scan = trackerState.futureScans.find((item) => item.id === merged._scanId);
    return scan && scan.stations ? scan.stations.checkBack || null : null;
  }
  return null;
}

function resurfaceBaseIntervalDays(mode) {
  if (mode === "futureScanCheckBack") return 7;
  return REFLECTION_RESURFACE_DAYS[mode] || REFLECTION_RESURFACE_DAYS.decisionJournal || 30;
}

// Adaptive resurfacing (GitHub research idea, inspired by the SM-2 spaced
// repetition algorithm behind Anki): the interval now responds to how the
// entry actually landed, instead of a fixed per-mode delay with only an
// ignore-count penalty. The direction is intentionally the OPPOSITE of a
// flashcard app - there, "remembered easily" means a longer gap; here,
// "still relevant" means you probably want it back SOONER (it's still
// live for you), and "resolved" means it can stretch way out or stop
// resurfacing entirely, since the point is helping you process it, not
// testing recall.
function resurfaceRatingIntervalDays(baseDays, rating) {
  if (rating === "resolved") return null;
  if (rating === "relevant") return Math.max(2, Math.round(baseDays * 0.6));
  return Math.round(baseDays * 1.6); // "somewhat" - partially settled, stretch out further
}

function resurfaceEntryAction(id, action) {
  const merged = allReflectionLikeEntries().find((entry) => entry.id === id);
  if (!merged) return;
  const original = resurfaceEntryOriginal(merged);
  if (!original) return;
  if (action === "snooze") {
    // A lighter option than rating it - "don't want to engage with this
    // right now at all" - keeps the old escalating-delay behavior rather
    // than forcing a rating out of someone who just wants it gone for now.
    original.ignoredCount = (original.ignoredCount || 0) + 1;
    if (original.ignoredCount >= 3) {
      original.dismissedAt = new Date().toISOString();
    } else {
      original.resurfaceAt = new Date(Date.now() + resurfaceBaseIntervalDays(merged.mode) * 86400000 * (original.ignoredCount + 1)).toISOString();
    }
    saveTrackerState();
    return;
  }
  const nextDays = resurfaceRatingIntervalDays(resurfaceBaseIntervalDays(merged.mode), action);
  original.resurfacedAt = new Date().toISOString();
  original.lastRating = action;
  original.ignoredCount = 0;
  if (nextDays === null) original.dismissedAt = new Date().toISOString();
  else original.resurfaceAt = new Date(Date.now() + nextDays * 86400000).toISOString();
  saveTrackerState();
}

function resurfacingCard() {
  const due = dueForResurfacing().slice(0, 3);
  if (!due.length) return "";
  return `
    <section class="future-reflection-list resurfacing-card">
      <div class="section-row">
        <div><p class="eyebrow">Worth another look</p><h3>Reflections resurfaced for you</h3></div>
        <span>${due.length}</span>
      </div>
      ${due.map((entry) => `
        <article class="future-reflection-item">
          <div>
            <strong>${escapeHTML(entry.mode === "decisionJournal" ? "A decision you journaled" : entry.mode === "weeklyLetter" ? "A letter to your past self" : entry.mode === "milestoneLetter" ? "A milestone letter" : entry.mode === "futureScanCheckBack" ? "A Future Scan check-back" : entry.mode === "storyActionChallenge" ? "An Inspire action challenge" : "A daily reflection")}</strong>
            <p>${escapeHTML(entry.content)}</p>
            <small>${escapeHTML(entry.displayTime || "")} - how does it look now?</small>
          </div>
          <div class="profile-actions">
            <button class="secondary-action compact-action" type="button" data-resurface-action="${escapeHTML(entry.id)}:relevant">Still relevant</button>
            <button class="secondary-action compact-action" type="button" data-resurface-action="${escapeHTML(entry.id)}:somewhat">Somewhat</button>
            <button class="secondary-action compact-action" type="button" data-resurface-action="${escapeHTML(entry.id)}:resolved">Resolved</button>
            <button class="text-action" type="button" data-resurface-action="${escapeHTML(entry.id)}:snooze">Not now</button>
          </div>
        </article>
      `).join("")}
    </section>
  `;
}

// Real Life Events (self-audit finding): the one category of "due" with
// a genuine external deadline the user entered themselves, not something
// Compass invented about their own reflections.
let realLifeEventError = "";

function myRealLifeEvents() {
  return trackerState.realLifeEvents.filter((event) => event.user_id === currentUserId());
}

function dueRealLifeEvents() {
  const now = Date.now();
  return myRealLifeEvents().filter((event) => event.status !== "done" && new Date(event.dueDate).getTime() <= now);
}

// Singapore milestone tracking (research-grounded finding): Youth STEPS
// (National Youth Council) found home ownership still ranks as a real,
// concrete adulthood marker for Singapore youth specifically, unlike the
// global "liquid adulthood" drift away from fixed milestones - but the
// only content Compass had for this (Real Cost of Living, Basic Tax
// Obligations) was static, read-once reference material, not something
// that gets actively tracked and remembered the way a real due date does.
// Deliberately event-based, not figure-based (no income ceilings, grant
// amounts, or CPF thresholds) - those change and Compass hand-writing a
// stale or wrong number would be real financial misinformation, unlike a
// practice roleplay getting a detail wrong. category: "milestone" reuses
// the exact same due-date/handled/recurrence machinery as a bill, just
// tagged and displayed separately, and feeds Your Story with its own
// phrasing (see growthTimelineEvents()).
const SG_MILESTONE_TEMPLATES = [
  "Started my first CPF contributions",
  "Submitted a BTO application",
  "BTO ballot results out",
  "HDB key collection - moved into my own home",
  "Completed National Service (ORD)"
];

function addRealLifeEvent({ title, dueDate, recurrence, note, category }) {
  trackerState.realLifeEvents.push({
    id: `rle-${Date.now()}`,
    user_id: currentUserId(),
    title: cleanText(title, 120),
    dueDate,
    recurrence: ["once", "monthly", "yearly"].includes(recurrence) ? recurrence : "once",
    note: cleanText(note, 240),
    category: category === "milestone" ? "milestone" : "recurring",
    status: "active",
    createdAt: new Date().toISOString(),
    lastHandledAt: null
  });
  saveTrackerState();
}

// Marking a one-off event handled closes it out; a recurring one rolls
// its dueDate forward by one cycle instead, the way a real bill or
// renewal actually works.
function markRealLifeEventHandled(id) {
  const event = trackerState.realLifeEvents.find((item) => item.id === id);
  if (!event) return;
  event.lastHandledAt = new Date().toISOString();
  if (event.recurrence === "once") {
    event.status = "done";
  } else {
    const next = new Date(`${event.dueDate}T00:00:00`);
    if (event.recurrence === "monthly") next.setMonth(next.getMonth() + 1);
    if (event.recurrence === "yearly") next.setFullYear(next.getFullYear() + 1);
    event.dueDate = dateKey(next);
  }
  saveTrackerState();
}

function deleteRealLifeEvent(id) {
  trackerState.realLifeEvents = trackerState.realLifeEvents.filter((item) => item.id !== id);
  saveTrackerState();
}

function realLifeEventsModal() {
  const events = myRealLifeEvents().filter((event) => event.status !== "done").sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate));
  const bills = events.filter((event) => event.category !== "milestone");
  const milestones = events.filter((event) => event.category === "milestone");
  const now = Date.now();
  const renderEvent = (event) => {
    const due = new Date(event.dueDate).getTime() <= now;
    return `
      <article class="ledger-entry">
        <p class="ledger-entry-stamp">${escapeHTML(new Date(event.dueDate).toLocaleDateString([], { month: "short", day: "numeric", year: "numeric" }))}${event.recurrence !== "once" ? ` - repeats ${event.recurrence}` : ""}${due ? " - due" : ""}</p>
        <p class="ledger-entry-text">${escapeHTML(event.title)}</p>
        ${event.note ? `<p class="ledger-entry-note">${escapeHTML(event.note)}</p>` : ""}
        <div class="profile-actions">
          <button class="secondary-action compact-action" type="button" data-handle-real-life-event="${escapeHTML(event.id)}">${event.category === "milestone" ? "Mark reached" : (event.recurrence === "once" ? "Mark done" : "Mark handled")}</button>
          <button class="text-action" type="button" data-delete-real-life-event="${escapeHTML(event.id)}">Remove</button>
        </div>
      </article>
    `;
  };
  return `
    <div class="modal-card assessment-modal" role="dialog" aria-modal="true" aria-labelledby="real-life-events-title">
      <div class="modal-top">
        <span class="risk-pill calm">Real Due Dates</span>
        <button class="ghost-circle" type="button" data-close aria-label="Close">x</button>
      </div>
      <h3 id="real-life-events-title">Real things, real dates</h3>
      <p class="muted">Rent, bills, renewals, appointments - things with an actual deadline outside this app, not a reminder Compass invented about your own reflections.</p>
      <div class="admin-form">
        <label>What is it?<input id="rle-title-input" type="text" maxlength="120" placeholder="e.g. Pay rent, Renew student pass, Dentist appointment"></label>
        <label>Due date<input id="rle-date-input" type="date"></label>
        <label>Repeats
          <select id="rle-recurrence-input">
            <option value="once">Just once</option>
            <option value="monthly">Every month</option>
            <option value="yearly">Every year</option>
          </select>
        </label>
        <label>Note (optional)<input id="rle-note-input" type="text" maxlength="240" placeholder="Optional details"></label>
        <label class="check-option">
          <input type="checkbox" id="rle-category-input">
          <span>This is a life milestone, not a recurring bill</span>
        </label>
      </div>
      ${realLifeEventError ? `<p class="form-error">${escapeHTML(realLifeEventError)}</p>` : ""}
      <button class="primary-action" type="button" data-save-real-life-event>Add</button>

      <div class="content-rail-title"><strong>Or track a Singapore milestone</strong><span></span></div>
      <p class="tiny-note">Home ownership specifically still shows up as a real adulthood marker for Singapore youth (Youth STEPS, National Youth Council) - unlike a bill, these get tracked with their own real date, not just read about once.</p>
      <div class="mirror-example-row">
        ${SG_MILESTONE_TEMPLATES.map((title) => `<button type="button" data-sg-milestone-template="${escapeHTML(title)}">${escapeHTML(title)}</button>`).join("")}
      </div>

      ${milestones.length ? `
        <div class="content-rail-title"><strong>Life milestones</strong><span>${milestones.length}</span></div>
        <div class="ledger-sheet">${milestones.map(renderEvent).join("")}</div>
      ` : ""}

      <div class="content-rail-title"><strong>Bills & deadlines</strong><span>${bills.length}</span></div>
      <div class="ledger-sheet">
        ${bills.length ? bills.map(renderEvent).join("") : `<p class="muted">Nothing tracked yet.</p>`}
      </div>
    </div>
  `;
}

