function skillGuideProgress(guideId) {
  return trackerState.skillGuideProgress[guideId] || { checkedSteps: [], completedAt: null };
}

function toggleSkillGuideStep(guideId, stepIndex) {
  const guide = SKILL_GUIDES.find((item) => item.id === guideId);
  if (!guide) return;
  const progress = trackerState.skillGuideProgress[guideId] || { checkedSteps: [], completedAt: null };
  const index = progress.checkedSteps.indexOf(stepIndex);
  if (index >= 0) progress.checkedSteps.splice(index, 1);
  else progress.checkedSteps.push(stepIndex);
  progress.completedAt = progress.checkedSteps.length >= guide.steps.length ? (progress.completedAt || new Date().toISOString()) : null;
  trackerState.skillGuideProgress[guideId] = progress;
  saveTrackerState();
}

// First-run onboarding (self-critique finding): the app had months of
// returning-user depth work but zero cold-start design - a brand-new user
// with no data saw only the generic Today's Desk fallback. This keyword
// match follows the same literal-keyword idiom already used elsewhere
// (see the reflection pattern-tags near legacyIssues, e.g. "conflict-avoidance")
// rather than an AI call, so the very first thing a new user sees never
// depends on a network round-trip.
// Expanded from 5 to 13 categories (self-critique finding): the original
// list only covered a fraction of what SKILL_GUIDES grew to, so most real
// answers fell through to the generic Growth Hub fallback despite the
// feature's whole promise being a specific first recommendation. Also fixes
// a real mismatch the narrower version shipped with: Ghost Roommate's
// personas (see GHOST_ROOMMATE_PERSONAS) are flatmates, not romantic
// partners, so romantic-relationship wording now routes to the
// end-a-relationship-well guide instead, and only literal roommate/flatmate
// wording routes to Ghost Roommate. "rent" moved out of payslip's keywords
// into renting's, since someone asking about renting a room almost never
// means their payslip.
