// Career Studio - Paycheck Reality Check (GitHub research idea, inspired by
// PolicyEngine's approach of computing real policy numbers instead of
// inventing plausible ones). "How much would I actually take home" is a
// concrete, nameable version of a vague "adulting" fear (taxes/CPF are
// confusing) - so this uses real, published Singapore figures (IRAS
// resident individual tax brackets, CPF Ordinary Wage employee rate/
// ceiling) rather than a fictional estimate, the same way the rest of
// Career Studio never invents facts about the user. Deliberately simplified
// (no bonus/relief/age-tier edge cases) and labeled as an estimate, not tax
// advice - the goal is turning an abstract fear into a concrete ballpark
// number, not filing an accurate return.
const SG_RESIDENT_TAX_BRACKETS_2024 = [
  { upTo: 20000, rate: 0 },
  { upTo: 30000, rate: 0.02 },
  { upTo: 40000, rate: 0.035 },
  { upTo: 80000, rate: 0.07 },
  { upTo: 120000, rate: 0.115 },
  { upTo: 160000, rate: 0.15 },
  { upTo: 200000, rate: 0.18 },
  { upTo: 240000, rate: 0.19 },
  { upTo: 280000, rate: 0.195 },
  { upTo: 320000, rate: 0.2 },
  { upTo: Infinity, rate: 0.22 }
];
const SG_CPF_EMPLOYEE_RATE = 0.2;
const SG_CPF_OW_CEILING_MONTHLY = 6800;

function computeSingaporeTakeHome(grossMonthly) {
  const monthly = Math.max(0, Number(grossMonthly) || 0);
  const cpfableMonthly = Math.min(monthly, SG_CPF_OW_CEILING_MONTHLY);
  const employeeCpfMonthly = cpfableMonthly * SG_CPF_EMPLOYEE_RATE;
  const annualIncome = monthly * 12;
  const chargeableIncome = Math.max(0, annualIncome - employeeCpfMonthly * 12);
  let annualTax = 0;
  let lowerBound = 0;
  for (const bracket of SG_RESIDENT_TAX_BRACKETS_2024) {
    if (chargeableIncome <= lowerBound) break;
    annualTax += (Math.min(chargeableIncome, bracket.upTo) - lowerBound) * bracket.rate;
    lowerBound = bracket.upTo;
  }
  const monthlyTax = annualTax / 12;
  return {
    grossMonthly: monthly,
    employeeCpfMonthly: Math.round(employeeCpfMonthly),
    monthlyTax: Math.round(monthlyTax),
    takeHomeMonthly: Math.round(monthly - employeeCpfMonthly - monthlyTax),
    annualTax: Math.round(annualTax)
  };
}

function calculatePaycheckReality() {
  const monthlyInput = modalLayer.querySelector("#paycheck-monthly-input");
  const grossMonthly = Number(monthlyInput ? monthlyInput.value : 0);
  if (!grossMonthly || grossMonthly <= 0) {
    trackerState.careerStudio.paycheckCheck = null;
    openModal("paycheckCalculator");
    return;
  }
  trackerState.careerStudio.paycheckCheck = { grossMonthly, result: computeSingaporeTakeHome(grossMonthly), updatedAt: new Date().toISOString() };
  saveTrackerState();
  openModal("paycheckCalculator");
}

function paycheckCalculatorView() {
  const saved = trackerState.careerStudio.paycheckCheck;
  const result = saved ? saved.result : null;
  return `
    <label>Gross monthly salary (S$)<input type="number" min="0" step="50" id="paycheck-monthly-input" value="${saved ? escapeHTML(String(saved.grossMonthly)) : ""}" placeholder="e.g. 3500"></label>
    <button class="primary-action compact-action" type="button" data-calculate-paycheck>Show my real take-home</button>
    ${result ? `
      <div class="resume-preview-card paycheck-result-card">
        <div class="paycheck-result-row"><span>Gross monthly pay</span><strong>S$${result.grossMonthly.toLocaleString()}</strong></div>
        <div class="paycheck-result-row"><span>CPF (yours - not lost, it's your own retirement/housing savings)</span><strong>-S$${result.employeeCpfMonthly.toLocaleString()}</strong></div>
        <div class="paycheck-result-row"><span>Estimated income tax</span><strong>-S$${result.monthlyTax.toLocaleString()}</strong></div>
        <div class="paycheck-result-row paycheck-result-final"><span>What actually lands in your bank account</span><strong>S$${result.takeHomeMonthly.toLocaleString()}</strong></div>
      </div>
      <p class="tiny-note">Estimate based on published IRAS resident individual tax brackets and CPF Ordinary Wage employee rate/ceiling. Not tax advice - real reliefs, bonuses, and CPF age tiers can change your actual numbers.</p>
    ` : ""}
  `;
}

// Career Studio - Job Matching (Ch.9). Deterministic, not AI-based: a fit
// score against a fixed catalog of well-known role archetypes, computed from
// the user's real saved Personal Blueprint (values/strengths/work/decision
// style). Standard, explainable scoring - no novel design needed here.
const WORK_STYLE_LABEL_BY_VALUE = Object.fromEntries(BLUEPRINT_WORK_SCENARIO.options.map((option) => [option.value, option.label]));
const DECISION_STYLE_LABEL_BY_VALUE = Object.fromEntries(BLUEPRINT_DECISION_SCENARIO.options.map((option) => [option.value, option.label]));

const CAREER_ROLE_ARCHETYPES = [
  { id: "data-analyst", title: "Data & Research Analyst", description: "Finding patterns in information and turning them into clear answers.", values: ["Growth", "Achievement"], strengths: ["Pattern recognition", "Technical problem-solving"], workStyle: ["deep-focus-blocks"], decisionStyle: ["research-heavy"] },
  { id: "ux-product-designer", title: "UX / Product Designer", description: "Shaping how a product looks, feels, and solves real user problems.", values: ["Creativity", "Growth"], strengths: ["Creativity", "Empathy"], workStyle: ["flexible", "collaborative"], decisionStyle: ["quick-plan"] },
  { id: "software-engineer", title: "Software Engineer", description: "Building and problem-solving with code, usually in focused stretches.", values: ["Growth", "Achievement", "Independence"], strengths: ["Technical problem-solving", "Pattern recognition", "Persistence"], workStyle: ["deep-focus-blocks"], decisionStyle: ["research-heavy", "just-start"] },
  { id: "marketing-brand", title: "Marketing & Brand", description: "Telling a story about a product or idea that gets people to care.", values: ["Creativity", "Connection", "Adventure"], strengths: ["Creativity", "Written communication"], workStyle: ["collaborative", "flexible"], decisionStyle: ["quick-plan"] },
  { id: "people-hr", title: "People & HR", description: "Helping people do their best work and resolving what gets in the way.", values: ["Connection", "Fairness"], strengths: ["Empathy", "Organisation", "Leadership"], workStyle: ["collaborative"], decisionStyle: ["ask-someone"] },
  { id: "operations-pm", title: "Operations / Project Management", description: "Keeping many moving parts on track toward a deadline.", values: ["Stability", "Achievement"], strengths: ["Organisation", "Leadership", "Persistence"], workStyle: ["short-bursts", "deep-focus-blocks"], decisionStyle: ["quick-plan"] },
  { id: "sales-partnerships", title: "Sales & Partnerships", description: "Building relationships and making the case for why something is worth it.", values: ["Achievement", "Adventure", "Connection"], strengths: ["Leadership", "Written communication"], workStyle: ["collaborative", "flexible"], decisionStyle: ["just-start"] },
  { id: "finance-accounting", title: "Finance / Accounting", description: "Making sure the numbers are right and the plan is sound.", values: ["Stability", "Fairness"], strengths: ["Organisation", "Pattern recognition"], workStyle: ["deep-focus-blocks"], decisionStyle: ["research-heavy"] },
  { id: "teaching-training", title: "Teaching / Training", description: "Helping other people understand something you already know.", values: ["Connection", "Growth"], strengths: ["Empathy", "Written communication", "Leadership"], workStyle: ["collaborative"], decisionStyle: ["ask-someone"] },
  { id: "creative-content", title: "Creative / Content", description: "Making things - writing, video, design - that people want to consume.", values: ["Creativity", "Adventure"], strengths: ["Creativity", "Written communication"], workStyle: ["flexible"], decisionStyle: ["just-start"] }
];

function scoreCareerRole(role, blueprint) {
  const matchedValues = role.values.filter((value) => blueprint.values.includes(value));
  const matchedStrengths = role.strengths.filter((strength) => blueprint.strengths.includes(strength));
  const workMatch = role.workStyle.includes(blueprint.workStyle);
  const decisionMatch = role.decisionStyle.includes(blueprint.decisionStyle);
  const score = matchedValues.length * 2 + matchedStrengths.length * 2 + (workMatch ? 1 : 0) + (decisionMatch ? 1 : 0);
  const max = role.values.length * 2 + role.strengths.length * 2 + 2;
  const percent = max ? Math.round((score / max) * 100) : 0;
  const matchedTraits = [...matchedValues, ...matchedStrengths];
  if (workMatch) matchedTraits.push(WORK_STYLE_LABEL_BY_VALUE[blueprint.workStyle] || blueprint.workStyle);
  if (decisionMatch) matchedTraits.push(DECISION_STYLE_LABEL_BY_VALUE[blueprint.decisionStyle] || blueprint.decisionStyle);
  // Skill gap (GitHub research idea, inspired by open-source skill-gap
  // analyzers): the same comparison scoreCareerRole already does, just
  // keeping the values/strengths this role wants that the Blueprint
  // doesn't have yet - each one becomes a real Build Mode training goal
  // instead of a dead-end "you're not a fit" readout.
  const missingTraits = [...role.values.filter((value) => !blueprint.values.includes(value)), ...role.strengths.filter((strength) => !blueprint.strengths.includes(strength))];
  return { role, percent, matchedTraits, missingTraits };
}

function jobMatchResults() {
  const blueprint = latestBlueprint();
  if (!blueprint) return null;
  return CAREER_ROLE_ARCHETYPES.map((role) => scoreCareerRole(role, blueprint)).sort((a, b) => b.percent - a.percent).slice(0, 5);
}

// Inferred purely from real signals already saved elsewhere (Blueprint,
// resume/portfolio, completed interview sessions, a paycheck check) -
// deliberately not a manual "what stage are you at" picker, since that
// drifts from reality the moment it's not updated. "Negotiating" is the
// one genuinely indirect inference (a paycheck check doesn't prove a
// real offer exists), so its own label says so honestly instead of
// stating it as fact.
function careerStageForUser() {
  const myId = currentUserId();
  if (!latestBlueprint()) {
    return { label: "Exploring", detail: "Still figuring out direction - that's the real starting point, not a gap.", nextLabel: "Start Discover Yourself", nextOpen: "discoverYourself" };
  }
  if (!trackerState.careerStudio.resume && !trackerState.careerStudio.portfolio) {
    return { label: "Preparing", detail: "Real direction is saved - next is actually getting a resume or portfolio written.", nextLabel: "Open Resume Builder", nextOpen: "resumeBuilder" };
  }
  const completedInterviews = trackerState.careerStudio.interviewSessions.filter((session) => session.user_id === myId && session.completedAt).length;
  if (!completedInterviews) {
    return { label: "Applying", detail: "Materials are ready - interview practice is the next real rep before the real thing.", nextLabel: "Start Interview Practice", nextOpen: "interviewPractice" };
  }
  if (!trackerState.careerStudio.paycheckCheck) {
    return { label: "Interviewing", detail: "Real interview practice is happening - once a real offer gets close, check what it actually becomes after CPF and tax.", nextLabel: "Check a paycheck", nextOpen: "paycheckCalculator" };
  }
  return { label: "Negotiating (a guess, not a fact)", detail: "This is inferred from checking a paycheck reality, not from knowing there's a real offer - if that's not what's actually happening, ignore this label.", nextLabel: "Review Job Matching", nextOpen: "jobMatching" };
}

// Fed into requestCompassAI's context (see context.careerSnapshot) - the
// existing missingTraits from jobMatchResults, not a new skill-gap
// analysis, just letting 2BB's chat reference the same real gaps that
// jobMatchingView() already surfaces as "Train: X" buttons.
function careerSnapshotForAI() {
  const results = jobMatchResults();
  if (!results || !results.length) return null;
  const top = results[0];
  return { stage: careerStageForUser().label, topRole: top.role.title, fitPercent: top.percent, missingTraits: top.missingTraits };
}

function jobMatchingView() {
  const results = jobMatchResults();
  if (!results) {
    return `
      <div class="empty-state-card">
        <p class="muted">Job matching uses your saved Personal Blueprint (values, strengths, work style) - complete that first.</p>
        <button class="primary-action" type="button" data-close-and-open="discoverYourself">Start Discover Yourself</button>
      </div>
    `;
  }
  return `
    <p class="muted">Based on your saved Personal Blueprint - a starting point for exploration, not a verdict on what you should do.</p>
    ${jobMatchingStarGapHint()}
    <div class="action-stack">
      ${results.map((result, index) => `
        <div class="job-match-card">
          <div class="modal-action-row"><strong>${escapeHTML(result.role.title)}</strong><span class="risk-pill calm">${result.percent}% fit</span></div>
          <p class="muted">${escapeHTML(result.role.description)}</p>
          ${result.matchedTraits.length ? `<div class="chip-row">${result.matchedTraits.map((trait) => `<span class="mini-chip">${escapeHTML(trait)}</span>`).join("")}</div>` : ""}
          ${result.missingTraits.length ? `
            <p class="tiny-note">Skill gap for this role:</p>
            <div class="chip-row">${result.missingTraits.map((trait) => `<button type="button" class="mini-chip gap-chip" data-train-skill-gap="${escapeHTML(trait)}" data-train-skill-gap-role="${escapeHTML(result.role.title)}">Train: ${escapeHTML(trait)}</button>`).join("")}</div>
          ` : ""}
          ${index === 0 ? `<button class="secondary-action compact-action" type="button" data-set-career-aspiration="${escapeHTML(result.role.title)}">Set as career aspiration &amp; find opportunities</button>` : ""}
        </div>
      `).join("")}
    </div>
  `;
}

